import { useState, useMemo, useCallback } from "react"
import { FindingsSearchHelper } from "../utils/searchHelper"
import { Finding } from "@roo/IBM/modernFindings/types"

export const useFindingsFilter = (findings: Finding[], currentGroupBy: string) => {
	const [searchTerm, setSearchTerm] = useState("")
	const [activeFilters, setActiveFilters] = useState<{ [key: string]: string }>({})
	const [sourceFilters, setSourceFilters] = useState<Set<string>>(new Set())

	const toggleSourceFilter = useCallback((source: string) => {
		setSourceFilters((prev) => {
			const newSet = new Set(prev)
			if (newSet.has(source)) {
				newSet.delete(source)
			} else {
				newSet.add(source)
			}
			return newSet
		})
	}, [])

	const hasActiveSourceFilters = sourceFilters.size > 0

	const availableSources = useMemo(() => {
		const sourcesInFindings = new Set<string>()
		findings.forEach((finding) => {
			if (finding.source) {
				sourcesInFindings.add(finding.source)
			}
		})
		return sourcesInFindings
	}, [findings])

	const availableFilters = useMemo(() => {
		const filters: { [key: string]: Set<string> } = {}
		findings.forEach((finding) => {
			switch (currentGroupBy) {
				case "type":
					if (!filters.type) filters.type = new Set()
					filters.type.add(finding.type)
					break
				case "severity":
					if (!filters.severity) filters.severity = new Set()
					filters.severity.add(finding.meta?.severity || "unknown")
					break
				case "category":
					if (!filters.category) filters.category = new Set()
					filters.category.add(finding.meta?.category || "uncategorized")
					break
				default: {
					if (!filters.file) filters.file = new Set()
					const filename = finding.uri.path.split("/").pop() || finding.uri.path
					filters.file.add(filename)
					break
				}
			}
		})

		return Object.fromEntries(Object.entries(filters).map(([key, set]) => [key, Array.from(set)]))
	}, [findings, currentGroupBy])

	const filteredFindings = useMemo(() => {
		let filtered = findings

		// Apply source filters (multi-select)
		if (sourceFilters.size > 0) {
			filtered = filtered.filter((finding) => finding.source && sourceFilters.has(finding.source))
		}

		// Apply active filters
		Object.entries(activeFilters).forEach(([filterKey, filterValue]) => {
			if (filterValue === "all") return

			filtered = filtered.filter((finding) => {
				if (filterKey === "type") return finding.type === filterValue

				if (filterKey === "file") {
					const filename = finding.uri.path.split("/").pop() || finding.uri.path
					return filename === filterValue
				}
				return finding.meta?.[filterKey] === filterValue
			})
		})

		if (searchTerm) {
			filtered = FindingsSearchHelper.searchFindings(filtered, searchTerm)
		}

		return filtered
	}, [findings, activeFilters, searchTerm, sourceFilters])

	const clearAllFilters = () => {
		setSearchTerm("")
		setActiveFilters({})
		setSourceFilters(new Set())
	}

	return {
		searchTerm,
		setSearchTerm,
		activeFilters,
		setActiveFilters,
		availableFilters,
		availableSources,
		filteredFindings,
		clearAllFilters,
		sourceFilters,
		toggleSourceFilter,
		hasActiveSourceFilters,
	}
}
