import { Finding } from "@roo/IBM/modernFindings/types"

export class FindingsSearchHelper {
	static searchFindings(findings: Finding[], searchTerm: string): Finding[] {
		if (!searchTerm.trim()) {
			return findings
		}

		const lowerSearchTerm = searchTerm.toLowerCase()

		return findings.filter((finding) => {
			if (finding.title.toLowerCase().includes(lowerSearchTerm)) {
				return true
			}

			if (finding.content?.toLowerCase().includes(lowerSearchTerm)) {
				return true
			}

			if (finding.uri.path?.toLowerCase().includes(lowerSearchTerm)) {
				return true
			}

			if (finding.meta) {
				const metadataValues = Object.values(finding.meta)
				if (
					metadataValues.some(
						(value) => typeof value === "string" && value.toLowerCase().includes(lowerSearchTerm),
					)
				) {
					return true
				}
			}

			return false
		})
	}
}
