type Severity = "critical" | "high" | "medium" | "low"

const SEVERITY_COLORS: Record<Severity, string> = {
	critical: "#f14c4c",
	high: "#f14c4c",
	medium: "#cca700",
	low: "#3794ff",
} as const

const DEFAULT_COLOR = "#888888"

export const getSeverityColor = (severity: string): string =>
	SEVERITY_COLORS[(severity ?? "").toLowerCase() as Severity] ?? DEFAULT_COLOR
export const getStatusColor = (status: string): string => {
	const colors: Record<string, string> = {
		resolved: "#3aeb34",
		"in-progress": "#cca700",
		open: "#f14c4c",
	}
	return colors[status] || "#888888"
}

export const getSeverityIcon = (severity: string): string => {
	const icons: Record<string, string> = {
		critical: "error",
		high: "error",
		medium: "warning",
		low: "info",
	}
	return icons[severity] || "info"
}

export const getCategoryIcon = (icon: string, category: string): string => {
	const icons: Record<string, string> = {
		maintainability: "wrench",
		security: "lock",
		performance: "zap",
		functionality: "gear",
		style: "paintcan",
	}
	return icons[category] || icon
}
