import { StrictMode } from "react"
import { createRoot } from "react-dom/client"

import "./finding.css"
import "@vscode/codicons/dist/codicon.css"
import { BobFindingsApp } from "./ibm/components/panel/bobFindingsApp"
import enIbm from "./i18n/locales/en/ibm.json"
import i18next from "i18next"
import { I18nextProvider, initReactI18next } from "react-i18next"


// Lets just use ibm.json as we don't need anything besides that for now
i18next
    .use(initReactI18next)
    .init({
        lng: "en",
        fallbackLng: "en",
        resources: {
            en: {
                ibm: enIbm
            }
        },
        interpolation: {
            escapeValue: false
        }
    })
createRoot(document.getElementById("root")!).render(
    <StrictMode>
        <I18nextProvider i18n={i18next}>
            <BobFindingsApp />
        </I18nextProvider>
    </StrictMode>,
)