import React, { useState, useEffect, useCallback, useMemo } from "react"
import { GenericFindingsView } from "./GenericFindingView"
import { vscode } from "@/utils/vscode"
import { FindingDetailPanel } from "./FindingDetailPanel"
import { useTranslation } from "react-i18next"
import { Finding, FindingAction, SourceIdentifier } from "@roo/IBM/modernFindings/types"
import { FindingsWebviewExtensionMessage, FindingsWebviewRequestMessage } from "@roo/IBM/findings/FindingsWebviewMessage"
import { WebviewMessage } from "@roo/WebviewMessage"

export const BobFindingsApp: React.FC = () => {
	const { t } = useTranslation()

	const [allFindings, setAllFindings] = useState<Finding[]>([])
	const [sources, setSources] = useState<SourceIdentifier[]>([]);
	const [actionsForFinding, setActionsForFinding] = useState<FindingAction[]>([]);
	const [selectedFindingId, setSelectedFindingId] = useState<string | null>(null)
	const [processingActions, setProcessingActions] = useState<Set<string>>(new Set())

	const sendRequest = (req: FindingsWebviewRequestMessage) => {
		return vscode.postMessage(req as unknown as WebviewMessage);
	}

	const sortFindings = (findings: Finding[]) => {
		return findings.sort((a, b) => a.range.start.line - b.range.start.line);
	}

	const handleMessage = useCallback((event: MessageEvent) => {
		const message = event.data as FindingsWebviewExtensionMessage
		switch (message.type) {
			case `availableSources`:
				setSources(prev => {
					if (prev.length === message.sources.length &&
						prev.every((s, i) => s.slug === message.sources[i]?.slug)) {
						return prev;
					}
					return message.sources;
				});
				break;

			case `setFindings`:
				setAllFindings(() => sortFindings(Object.values(message.allFindings).flat(2)));
				break;
			case `updateFindingsForUri`:
				setAllFindings(prev => sortFindings(prev.filter(f => f.uri.path !== message.uri.path).concat(message.findings)));
				break;
			case `availableActions`:
				if (message.findingId === selectedFindingId) {
					setActionsForFinding(() => message.actions);
				}
				break;
			case `actionFinish`:
				setProcessingActions((prev) => {
					if (!prev.has(message.actionId)) return prev
					const next = new Set(prev)
					next.delete(message.actionId)
					return next
				})

				// Let's update the actions in case they change after something run.
				sendRequest({ type: `getActions`, findingId: message.findingId })
				break;
		}
	}, [selectedFindingId])
	const memoizedSources = useMemo(() => sources, [sources])
	const memoizedActions = useMemo(() => actionsForFinding, [actionsForFinding])
	const memoizedFindings = useMemo(() => allFindings, [allFindings])

	useEffect(() => {
		sendRequest({ type: "ready" })

		window.addEventListener("message", handleMessage)

		return () => {
			window.removeEventListener("message", handleMessage)
		}
	}, [handleMessage])

	const selectedFinding = useMemo(() => {
		return selectedFindingId ? allFindings.find((f) => f.id === selectedFindingId) || null : null
	}, [allFindings, selectedFindingId])

	const handleSearchChange = useCallback(() => {
		setSelectedFindingId(null)
	}, [])

	const handleDetailPanelAction = useCallback(
		(actionId: string, finding: Finding) => {
			if (finding && finding.id) {
				setProcessingActions((prev) => {
					if (prev.has(actionId)) return prev
					const next = new Set(prev)
					next.add(actionId)
					return next
				})
				sendRequest({
					type: `invokeAction`,
					actionId,
					findingId: finding.id
				})
			} else {
				console.warn(`No original finding found for ID: ${finding.id}`)
			}
		},
		[],
	)

	const handleFindingSelect = useCallback((finding: Finding | undefined) => {
		if (finding && finding.id) {
			setSelectedFindingId(finding.id)
		} else {
			setSelectedFindingId(null)
		}
	}, [])

	useMemo(() => {
		if (selectedFindingId) {
			sendRequest({ type: `getActions`, findingId: selectedFindingId })
		}
	}, [selectedFindingId])

	const emptyStateContent = useMemo(
		() => (
			<div className="p-4 text-center text-vscode-descriptionForeground h-screen flex items-center justify-center">
				<div>
					<h3>{t("ibm:findings.app.empty.title")}</h3>
					<p>{t("ibm:findings.app.empty.message")}</p>
				</div>
			</div>
		),
		[t],
	)

	if (allFindings.length === 0) {
		return emptyStateContent
	}
	return (
		<div className="h-screen w-full">
			<vscode-split-layout
				className="h-full w-full"
				style={{ "--vscode-split-view-sash-size": "2px", height: "100vh" } as React.CSSProperties}>
				<div slot="start" className="overflow-auto h-full">
					<GenericFindingsView
						findings={memoizedFindings}
						sources={memoizedSources}
						groupBy="file"
						onFindingSelect={handleFindingSelect}
						onSearchChange={handleSearchChange}
					/>
				</div>
				<div slot="end" className="overflow-auto h-full">
					<FindingDetailPanel
						finding={selectedFinding}
						availableActions={memoizedActions}
						onAction={handleDetailPanelAction}
						processingActions={processingActions}
					/>
				</div>
			</vscode-split-layout>
		</div>
	)
}
