import React, { useMemo, memo } from "react"
import "@vscode-elements/elements"
import "@vscode-elements/elements/dist/vscode-badge"
import "@vscode-elements/elements/dist/vscode-button"
import "@vscode-elements/elements/dist/vscode-divider"
import { SimpleMarkdown } from "../common/SimpleMarkdown"
import { useTranslation } from "react-i18next"
import { Finding, FindingAction } from "@roo/IBM/modernFindings/types"

type FindingActionPress = (actionId: string, finding: Finding) => void;

interface FindingDetailPanelProps {
	finding: Finding | null
	onAction?: FindingActionPress,
	availableActions?: FindingAction[]
	processingActions?: Set<string>
}

const EMPTY_PROCESSING_ACTIONS = new Set<string>()

const EmptyState = memo(({ t }: { t: (key: string) => string }) => (
	<div className="p-6 text-center text-vscode-descriptionForeground bg-vscode-sideBar-background h-full flex flex-col justify-center items-center">
		<div className="text-5xl mb-4">📋</div>
		<h3>{t("ibm:findings.detail.empty.title")}</h3>
		<p>{t("ibm:findings.detail.empty.message")}</p>
	</div>
))

interface ActionButtonProps {
	action: FindingAction
	finding: Finding
	isProcessing: boolean
	findingIsBusy: boolean
	onAction?: FindingActionPress
	t: (key: string) => string
}

const ActionButton = memo(({ action, finding, isProcessing, findingIsBusy, onAction }: ActionButtonProps) => (
	<vscode-button
		onClick={() => onAction?.(action.id, finding)}
		disabled={isProcessing || findingIsBusy ? true : undefined}
		title={action.label}>
		{isProcessing ? (
			<>
				<span className="codicon codicon-loading codicon-modifier-spin mr-1" />
				{action.label}
			</>
		) : (
			<>
				<span className={`codicon codicon-${action.icon || `info`} mr-1`} />
				{action.label}
			</>
		)}
	</vscode-button>
))

export const FindingDetailPanel: React.FC<FindingDetailPanelProps> = memo(
	({ finding, onAction, processingActions = EMPTY_PROCESSING_ACTIONS, availableActions }) => {
		const { t } = useTranslation()

		const locationText = useMemo(() => (finding ? `${finding.uri.path}:${finding.range.start.line+1}` : ""), [finding])

		if (!finding) {
			return <EmptyState t={t} />
		}

		const findingIsBusy = availableActions ? availableActions.some(a => processingActions.has(a.id)) : false

		return (
			<div className="h-full flex flex-col font-vscode-font text-vscode-foreground bg-vscode-sideBar-background">
				<div className="p-2 border-b border-vscode-sideBar-border bg-vscode-sideBar-background">
					<div className=" font-semibold mb-1 text-vscode-foreground text-lg">{finding.title}</div>
				</div>

				<div className="flex-1 flex flex-col px-2 py-2 min-h-0">
					<div className="overflow-y-auto flex-1 mb-4 min-h-[80px]"> {/* ibm_change: Added min-h-[80px] to prevent description from disappearing on small screens */}
						<SimpleMarkdown content={finding.content} />
					</div>

					<div className="p-3 bg-vscode-editor-background border border-vscode-input-border rounded mb-4 font-vscode-editor-font text-vscode-editor-font-size break-all">
						<strong>{t("ibm:findings.detail.location")}</strong> {locationText}
					</div>

					{availableActions && availableActions.length > 0 && (
						<div className="flex gap-2 flex-wrap finding-actions-container"> {/* ibm_change: Added finding-actions-container class for responsive button styling */}
							{availableActions.map((action) => {
								const isProcessing = processingActions.has(action.id)
								return (
									<ActionButton
										key={action.id}
										action={action}
										finding={finding}
										findingIsBusy={findingIsBusy}
										isProcessing={isProcessing}
										onAction={onAction}
										t={t}
									/>
								)
							})}
						</div>
					)}
				</div>
			</div>
		)
	},
)
