import React, { useState, useMemo, useCallback, useRef, useEffect, memo } from "react"
import { useFindingsFilter } from "../../hooks/useFindingsFilter"
import { getStatusColor } from "../../utils/findingHelpers"
import { useTranslation } from "react-i18next"
import "@vscode-elements/elements"
import "@vscode-elements/elements/dist/vscode-tree"
import "@vscode-elements/elements/dist/vscode-badge"
import "@vscode-elements/elements/dist/vscode-button"
import "@vscode-elements/elements/dist/vscode-textfield"
import "@vscode-elements/elements/dist/vscode-divider"
import { TreeItem } from "@vscode-elements/elements/dist/vscode-tree/vscode-tree"
import type { VscTreeSelectEvent } from "@vscode-elements/elements/dist/vscode-tree/vscode-tree"
import { Finding, SourceIdentifier } from "@roo/IBM/modernFindings/types"
import { Popover, PopoverTrigger, PopoverContent } from "@/components/ui/popover"

interface GenericFindingsViewProps {
	findings: Finding[]
	sources: SourceIdentifier[]
	groupBy?: GroupByOption
	onFindingSelect?: (finding: Finding | undefined) => void
	onSearchChange?: () => void
}

type GroupByOption = "file" | "type" | "severity" | "category"

const GROUP_BY_OPTIONS = [
	{ value: "file", labelKey: "ibm:findings.groupBy.file" },
	{ value: "type", labelKey: "ibm:findings.groupBy.type" },
	{ value: "severity", labelKey: "ibm:findings.groupBy.severity" },
] as const

const getGroupInfo = (finding: Finding, groupBy: GroupByOption, sources: SourceIdentifier[], t: (key: string) => string) => {
	switch (groupBy) {
		case "type": {
			const groupKey = finding.type
			const groupLabel = sources.find((c) => c.slug === finding.source)?.label || finding.type
			return { groupKey, groupLabel }
		}
		case "severity": {
			const severityKey = finding.meta.severity || t("ibm:findings.unknown")
			return {
				groupKey: severityKey,
				groupLabel: severityKey.charAt(0).toUpperCase() + severityKey.slice(1),
			}
		}
		case "category": {
			const categoryKey = finding.meta.category || t("ibm:findings.uncategorized")
			return {
				groupKey: categoryKey,
				groupLabel: categoryKey.charAt(0).toUpperCase() + categoryKey.slice(1),
			}
		}
		default:
			return { groupKey: finding.uri.path, groupLabel: finding.uri.path.split("/").pop() || finding.uri.path }
	}
}

const getGroupIcon = (
	iconType: "branch" | "leaf" | "open",
	groupBy: GroupByOption,
	findings: Finding[],
	sources: SourceIdentifier[],
) => {
	if (groupBy === "type") {
		const typeConfig = sources.find((c) => c.slug === findings[0]?.source)
		return typeConfig?.icon || (iconType === "open" ? "folder-opened" : "folder")
	}

	if (groupBy === "file") {
		return "file"
	}

	return iconType === "open" ? "folder-opened" : "folder"
}

const createFindingNode = (finding: Finding, sources: SourceIdentifier[], t: (key: string) => string): TreeItem => {
	const source = sources.find((c) => c.slug === finding.source)

	const decorations = []

	// ============================================
	// This stuff is very review centric
	// ============================================

	if (finding.meta?.status) {
		decorations.push({
			appearance: "text" as const,
			content: finding.meta.status,
			color: getStatusColor(finding.meta.status),
			visibleWhen: "always" as const,
		})
	}

	const icon = source?.icon || `info`;
	// let icon = config?.icon
	// if (finding._meta.category) {
	// 	icon = getCategoryIcon(config?.icon, finding._meta.category)
	// }

	// ============================================

	return {
		label: `${finding.title}:${finding.range.start.line + 1}`,
		value: `finding-${finding.id}`,
		icons: {
			branch: icon,
			leaf: icon,
			open: icon,
		},
		tooltip: `${finding.title}${t("ibm:findings.lineLabel")}${finding.range.start.line + 1}`,
		decorations,
	}
}

interface FilterSelectProps {
	filterKey: string
	options: string[]
	activeValue: string
	onChange: (filterKey: string, value: string) => void
	t: (key: string) => string
}

const FilterSelect = memo(({ filterKey, options, activeValue, onChange, t }: FilterSelectProps) => (
	<select
		className="bg-vscode-input-background text-vscode-input-foreground border border-vscode-input-border rounded px-2 py-1 h-8 text-sm !outline-none w-auto focus:border-vscode-focusBorder"
		value={activeValue}
		tabIndex={0}
		onChange={(e) => onChange(filterKey, e.target.value)}>
		<option value="all">{t(`ibm:findings.filter.${filterKey}`)}</option>
		{options.map((option) => (
			<option key={option} value={option}>
				{option}
			</option>
		))}
	</select>
))

const EmptyState = memo(({ t, onClearFilters }: { t: (key: string) => string; onClearFilters: () => void }) => (
	<div className="p-6 text-center text-vscode-descriptionForeground bg-vscode-sideBar-background">
		<h3>{t("ibm:findings.empty.title")}</h3>
		<p>{t("ibm:findings.empty.message")}</p>
		<vscode-button onClick={onClearFilters}>{t("ibm:findings.empty.clearFilters")}</vscode-button>
	</div>
))

export const GenericFindingsView: React.FC<GenericFindingsViewProps> = memo(
	({ findings, sources, groupBy = "file", onFindingSelect, onSearchChange }) => {
		const { t } = useTranslation()
		const [expandedNodes, setExpandedNodes] = useState<Set<string>>(new Set())
		const [currentGroupBy, setCurrentGroupBy] = useState<GroupByOption>(groupBy)
		const treeRef = useRef<any>(null)

		const {
			searchTerm,
			setSearchTerm,
			activeFilters,
			setActiveFilters,
			availableFilters,
			availableSources,
			filteredFindings,
			clearAllFilters,
			sourceFilters,
			toggleSourceFilter,
			hasActiveSourceFilters,
		} = useFindingsFilter(findings, currentGroupBy)

		const groupedFindings = useMemo(() => {
			const grouped = new Map<string, Finding[]>()

			filteredFindings.forEach((finding) => {
				const { groupKey } = getGroupInfo(finding, currentGroupBy, sources, t)
				if (!grouped.has(groupKey)) {
					grouped.set(groupKey, [])
				}
				grouped.get(groupKey)!.push(finding)
			})

			return grouped
		}, [filteredFindings, currentGroupBy, sources, t])

		const treeData = useMemo<TreeItem[]>(() => {
			if (groupedFindings.size === 0) {
				return []
			}
			return Array.from(groupedFindings.entries()).sort((a, b) => a[0].localeCompare(b[0], undefined, { sensitivity: 'base' })).map(([groupKey, groupFindings]) => {
				const { groupLabel } = getGroupInfo(groupFindings[0], currentGroupBy, sources, t)
				const groupValue = `group-${groupKey}`
				const isExpanded = expandedNodes.has(groupValue)

				return {
					label: groupLabel,
					value: groupValue,
					open: isExpanded,
					subItems: groupFindings.map((finding) => createFindingNode(finding, sources, t)),
					icons: {
						branch: getGroupIcon("branch", currentGroupBy, groupFindings, sources),
						leaf: getGroupIcon("leaf", currentGroupBy, groupFindings, sources),
						open: getGroupIcon("open", currentGroupBy, groupFindings, sources),
					},
					tooltip: `${groupLabel} (${t("ibm:findings.count", { count: groupFindings.length })})`,
					decorations: [
						{
							appearance: "counter-badge" as const,
							content: `${groupFindings.length}`,
							color: "#888888",
						},
					],
				}
			})
		}, [expandedNodes, currentGroupBy, sources, groupedFindings, t])

		const handleTreeSelect = useCallback(
			(event: VscTreeSelectEvent) => {
				const { value } = event.detail

				if (typeof value === "string" && value.startsWith("group-")) {
					setExpandedNodes((prev) => {
						const newSet = new Set(prev)
						if (newSet.has(value)) {
							newSet.delete(value)
						} else {
							newSet.add(value)
						}
						return newSet
					})
				} else if (typeof value === "string" && value.startsWith("finding-")) {
					const findingId = value.replace("finding-", "")
					const finding =
						filteredFindings.find((f) => f.id === findingId) || findings.find((f) => f.id === findingId)
					if (finding && onFindingSelect) {
						onFindingSelect(finding)
					}
				}
			},
			[findings, onFindingSelect, filteredFindings],
		)

		const handleFilterChange = useCallback(
			(filterKey: string, value: string) => {
				setActiveFilters((prev) => ({
					...prev,
					[filterKey]: value,
				}))
				onSearchChange?.()
			},
			[setActiveFilters, onSearchChange],
		)

		const handleGroupByChange = useCallback(
			(e: React.ChangeEvent<HTMLSelectElement>) => {
				setCurrentGroupBy(e.target.value as GroupByOption)
				onSearchChange?.()
			},
			[onSearchChange],
		)

		const handleSearchChange = useCallback(
			(e: any) => {
				setSearchTerm(e.target.value)
				onSearchChange?.()
			},
			[setSearchTerm, onSearchChange],
		)

		useEffect(() => {
			const treeElement = treeRef.current
			if (!treeElement) return

			const selectHandler = (event: CustomEvent) => {
				handleTreeSelect(event as VscTreeSelectEvent)
			}

			treeElement.addEventListener("vsc-tree-select", selectHandler)

			return () => {
				treeElement.removeEventListener("vsc-tree-select", selectHandler)
			}
		}, [handleTreeSelect])

		useEffect(() => {
			if (treeRef.current) {
				treeRef.current.data = treeData
			}
		}, [treeData])

		const filterComponents = useMemo(() => {
			return Object.entries(availableFilters).map(([filterKey, options]) => (
				<FilterSelect
					key={filterKey}
					filterKey={filterKey}
					options={options}
					activeValue={activeFilters[filterKey] || "all"}
					onChange={handleFilterChange}
					t={t}
				/>
			))
		}, [availableFilters, activeFilters, handleFilterChange, t])

		return (
			<div className="h-full flex flex-col font-vscode-font text-vscode-foreground bg-vscode-sideBar-background">
				<div className="p-2 bg-vscode-sideBar-background border-b border-vscode-sideBar-border flex-shrink-0">
					<div className="flex items-center gap-2 min-w-0">
						<div className="flex-1 min-w-24">
							<div className="relative w-full">
								<input
									type="text"
									value={searchTerm}
									onChange={handleSearchChange}
									placeholder={t("ibm:findings.search.placeholder")}
									className="w-full h-8 pl-8 pr-3 py-1 bg-vscode-input-background text-vscode-input-foreground border border-vscode-input-border rounded text-sm !outline-none focus:!border-vscode-focusBorder placeholder-vscode-input-placeholderForeground"
								/>
								<span
									className="codicon codicon-search absolute left-2 top-1/2 transform -translate-y-1/2 text-vscode-input-placeholderForeground pointer-events-none"
									style={{ fontSize: "14px" }}></span>
							</div>
						</div>

						{availableSources.size > 0 && (
							<Popover>
								<PopoverTrigger asChild>
									<button
										className="h-8 w-8 min-w-8 flex-shrink-0 flex items-center justify-center rounded hover:bg-vscode-toolbar-hoverBackground text-vscode-foreground cursor-pointer relative"
										title={t("ibm:findings.filter.sources")}
										aria-label={t("ibm:findings.filter.sources")}>
										<span className="codicon codicon-filter" style={{ fontSize: "16px" }} />
										{hasActiveSourceFilters && (
											<span className="absolute top-0.5 right-0.5 w-2 h-2 rounded-full bg-vscode-activityBarBadge-background" />
										)}
									</button>
								</PopoverTrigger>
								<PopoverContent align="start" className="w-56 p-0">
									<div className="p-3">
										<div className="font-medium text-sm mb-2">{t("ibm:findings.filter.sources")}</div>
										<div className="space-y-1">
											{sources
												.filter((source) => availableSources.has(source.slug))
												.map((source) => (
													<label
														key={source.slug}
														className="flex items-center gap-2 py-1 px-1 rounded hover:bg-vscode-list-hoverBackground cursor-pointer">
														<input
															type="checkbox"
															checked={sourceFilters.size === 0 || sourceFilters.has(source.slug)}
															onChange={() => toggleSourceFilter(source.slug)}
															className="w-4 h-4 accent-vscode-focusBorder"
														/>
														<span className="text-sm">{source.label}</span>
													</label>
												))}
										</div>
									</div>
								</PopoverContent>
							</Popover>
						)}

						<div className="flex items-center gap-2 flex-shrink-0 overflow-x-auto">
							{filterComponents}
							<select
								className="bg-vscode-input-background text-vscode-input-foreground border border-vscode-input-border rounded px-2 py-1 h-8 text-sm flex-shrink-0 !outline-none focus:!border-vscode-focusBorder
							"
								value={currentGroupBy}
								tabIndex={0}
								onChange={handleGroupByChange}
								style={{ minWidth: "100px", maxWidth: "150px" }}>
								{GROUP_BY_OPTIONS.map(({ value, labelKey }) => (
									<option key={value} value={value}>
										{t(labelKey)}
									</option>
								))}
							</select>
						</div>
					</div>
				</div>

				<div className="flex-1 overflow-auto">
					{filteredFindings.length === 0 || treeData.length === 0 ? (
						<EmptyState t={t} onClearFilters={clearAllFilters} />
					) : (
						<vscode-tree ref={treeRef} indent-guides={true} arrows={true} indent={0} />
					)}
				</div>
			</div>
		)
	},
)
